CREATE TABLE "sagitta_observe_events" (
  "id" bigint NOT NULL,
  "bucket" integer NOT NULL,
  "payload" text,
  "amount" numeric,
  "updated_at" timestamp with time zone DEFAULT now(),
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE INDEX idx_sag_obs_bucket ON public.sagitta_observe_events USING btree (bucket);
CREATE INDEX idx_sagitta_observe_events_bucket ON public.sagitta_observe_events USING btree (bucket);

